/* @lc app=leetcode id=1860 lang=kotlin */ class Solution { fun memLeak(m1: Int, m2: Int): IntArray = generateSequence(intArrayOf(m1, m2, 1)) { s -> s.let { if (maxOf(it[0], it[1]) < it[2]) intArrayOf(it[0], it[1], -it[2]) else if (it[0] >= it[1]) intArrayOf(it[0] - it[2], it[1], it[2] + 1) else intArrayOf(it[0], it[1] - it[2], it[2] + 1) } }.first { it[2] < 0 }.let { intArrayOf(-it[2], it[0], it[1]) } }